import { MakeLogicType, afterMount, connect, kea, path } from 'kea'
import { loaders } from 'kea-loaders'

import { projectLogic } from 'scenes/projectLogic'

import { mcpServerInstallationsList } from 'products/mcp_store/frontend/generated/api'
import type { MCPServerInstallationApi } from 'products/mcp_store/frontend/generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface taskConnectorsPickerLogicValues {
    currentProjectId: number | null // projectLogic
    installations: MCPServerInstallationApi[]
    installationsLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface taskConnectorsPickerLogicActions {
    loadInstallations: () => any
    loadInstallationsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadInstallationsSuccess: (
        installations: MCPServerInstallationApi[],
        payload?: any
    ) => {
        installations: MCPServerInstallationApi[]
        payload?: any
    }
}

export type taskConnectorsPickerLogicType = MakeLogicType<
    taskConnectorsPickerLogicValues,
    taskConnectorsPickerLogicActions
>

export const taskConnectorsPickerLogic = kea<taskConnectorsPickerLogicType>([
    path(['products', 'tasks', 'frontend', 'components', 'TaskConnectorsPicker', 'taskConnectorsPickerLogic']),
    connect(() => ({
        values: [projectLogic, ['currentProjectId']],
    })),
    loaders(({ values }) => ({
        installations: [
            [] as MCPServerInstallationApi[],
            {
                loadInstallations: async (): Promise<MCPServerInstallationApi[]> => {
                    const response = await mcpServerInstallationsList(String(values.currentProjectId))
                    return response.results
                },
            },
        ],
    })),
    afterMount(({ actions }) => {
        actions.loadInstallations()
    }),
])
